            target = _zone_links()[target]
            seen += 1
        if target in ("UTC", "GMT") or "/" not in target:
            return "Etc/UTC" if target in ("UTC", "GMT") else target
        return target
    return tz


_SUPPORTED = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}


def _locale(loc: str) -> str:
    loc = re.split(r"[.@]", loc.strip())[0].replace("_", "-")
    parts = loc.split("-")
    tag = parts[0].lower() + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _SUPPORTED:
        return tag
    if parts[0].lower() in _SUPPORTED:
        return parts[0].lower()
    return "en-US"


