    "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _round(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(ip: str, locale: str, sep: str) -> str:
    if locale == "es" and len(ip) == 4:
        return ip
    if locale == "en-IN" and len(ip) > 3:
        head, tail = ip[:-3], ip[-3:]
        chunks = []
        while len(head) > 2:
            chunks.insert(0, head[-2:])
            head = head[:-2]
        if head:
            chunks.insert(0, head)
        return sep.join(chunks + [tail])
    chunks = []
    while len(ip) > 3:
        chunks.insert(0, ip[-3:])
        ip = ip[:-3]
    chunks.insert(0, ip)
    return sep.join(chunks)


def _text(value: Decimal, currency: str, locale: str) -> str:
    digits = _digits(currency)
    dec, grp, before = _FMT[locale]
    neg = value < 0
    q = format(abs(value).quantize(Decimal(1).scaleb(-digits)), "f")
    ip, _, fp = q.partition(".")
    num = _group(ip, locale, grp) + (dec + fp if digits else "")
    if neg:
        num = "-" + num
    return f"{currency}{_NB}{num}" if before else f"{num}{_NB}{currency}"


